'use strict';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('en-ZA',{style:'currency',currency:'ZAR',maximumFractionDigits:0}).format(n||0),precise=n=>new Intl.NumberFormat('en-ZA',{style:'currency',currency:'ZAR'}).format(n||0),uid=()=>crypto.randomUUID(),today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Africa/Johannesburg'}),monthNow=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Johannesburg',year:'numeric',month:'2-digit'}).format(new Date()).slice(0,7);
let scenario={start:monthNow(),extraIncome:0,incomeMonths:1,extraTax:0,payment:0,term:12,principal:0};
let S,view='overview',month=monthNow(),query='',filter='',pending=null,serverMode=location.protocol!=='file:',saveQueue=Promise.resolve();
const key=JSON.parse($('#seed').textContent).storageKey||'finance-local-template-v1',metric=(title,n,sub='',cls='')=>`<div class="card"><div class="eyebrow">${title}</div><div class="metric ${cls}">${money(n)}</div><small>${sub}</small></div>`,btn=(text,action,cl='')=>`<button type="button" class="${cl}" data-action="${action}">${text}</button>`;
let toastTimer,autoSaveTimer,lastSnapshot=null,saveRevision=0,pendingWrites=0;
function toast(s){clearTimeout(toastTimer);$('#toast').textContent=s;$('#toast').style.display='block';toastTimer=setTimeout(()=>$('#toast').style.display='none',5000)}
function status(s){$('#saved').textContent=s;let mobile=$('#saveStatus');if(mobile)mobile.textContent=s}
function save(message='Changes saved'){clearTimeout(autoSaveTimer);autoSaveTimer=null;try{F.valid(S);let delta=F.changes(lastSnapshot,S);if(delta.length){S.changeLog||=[];S.changeLog.push({at:new Date().toISOString(),items:JSON.parse(JSON.stringify(delta))});S.changeLog=S.changeLog.slice(-100)}lastSnapshot=JSON.parse(JSON.stringify(S));let body=JSON.stringify(S),revision=++saveRevision;status('Saving…');pendingWrites++;const write=async()=>{try{if(serverMode){let r=await fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json','X-Finance-Local':'1'},body});if(!r.ok)throw Error('Local database could not save')}else localStorage.setItem(key,body);if(revision===saveRevision){status('Saved · '+new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'}));toast(message+(serverMode?' on this PC':' in this browser'))}return true}catch(e){status('Save failed · retry or export backup');toast('Save failed. Your edits are still on screen. Retry save or export a backup. '+e.message);return false}finally{pendingWrites--}};saveQueue=saveQueue.then(write,write);return saveQueue}catch(e){status('Save failed');toast('Save failed: '+e.message);return Promise.resolve(false)}}
function liveBudget(){let n=$('#liveBudget');if(n){let f=F.finance(S);n.textContent='Plan '+precise(f.spend)+' · take-home '+precise(f.net)+' · '+(f.surplus<0?'shortfall ':'available ')+precise(Math.abs(f.surplus))}}
function download(name,text,type='application/json'){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function monthRows(m=month){return S.transactions.filter(t=>t.date.startsWith(m))}
function categoryTotals(rows){return F.cats.map(category=>({category,amount:-F.sum(rows.filter(t=>t.category===category&&t.amount<0),t=>t.amount)})).filter(x=>x.amount).sort((a,b)=>b.amount-a.amount)}
function opts(values,value){return values.map(v=>`<option ${v===value?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('')}
function render(){document.querySelectorAll('nav button').forEach(b=>(b.classList.toggle('active',b.dataset.view===view),b.setAttribute?.('aria-current',b.dataset.view===view?'page':'false')));$('#title').textContent=({overview:'Financial overview',plan:'Build your monthly plan',transactions:'Every rand, accounted for',debts:'A clearer path out of debt',tax:'Tax & income targets',audit:'Close the month with confidence',settings:'Your details & evidence',trends:'Spending & income trends',scenarios:'What-if cash flow'})[view];$('#month').value=month;$('#content').innerHTML=({overview,plan,transactions,debts,tax:taxView,audit:auditView,settings,trends,scenarios})[view]();}
function overview(){let f=F.finance(S),payments=S.debts.filter(d=>d.paymentEnabled!==false&&d.paymentKind!=='interest-estimate'),unconfirmed=payments.filter(d=>!d.confirmed).length,last=S.transactions.map(t=>t.date).sort().at(-1);return `<section class="hero"><div><div class="eyebrow">REMAINING AFTER DEBT PAYMENTS</div><div class="big">${money(f.debtRoom)}</div><div class="muted">${f.debtRoom<0?'Debt instalments exceed take-home income before living costs.':'Before optional living costs, savings and extra debt payments.'}</div><div class="income-tags">${S.income.filter(i=>i.active).map(i=>`<span>${esc(i.name)}</span>`).join('')}<span>Income and debts first</span></div></div><div class="hero-side"><span class="pill ${f.debtRoom<0?'warning':''}">${f.debtRoom<0?'Debt payment gap':'Debt baseline'}</span>${btn('Review debt payments →','go:debts','primary')}</div></section><div class="grid">${metric('Take-home income',f.net,'After PAYE, tax reserve and payroll deductions')}${metric('Monthly debt payments',f.debtSpend,'Mortgage, vehicle and counted lender instalments')}${metric('Optional living costs',f.optionalSpend,'Only what you choose to include')}${metric('After chosen costs & savings',f.surplus,'Before extra debt repayments',f.surplus<0?'bad':'good')}</div>${unconfirmed?`<div class="notice">${unconfirmed} counted debt figures are dated or need confirmation. Unknown minimums may be recorded as zero; the total can be incomplete. Review lender statements before committing extra payments.</div>`:''}${(S.alerts||[]).slice(0,2).map(a=>`<details class="notice"><summary>${esc(a.title)}</summary><p>${esc(a.detail)}</p></details>`).join('')}<div class="split"><section class="card"><div class="row"><h2>Every debt payment in the baseline</h2>${btn('Edit register','go:debts')}</div>${payments.map(d=>`<div class="cash-line"><span>${esc(d.name)}<small class="source-line">${esc(d.asOf||'Date needed')} · ${d.confirmed?'confirmed current':'needs current confirmation'}</small></span><strong>${precise(d.minimum)}</strong></div>`).join('')||'<p>Add your debts and their monthly instalments to start.</p>'}<div class="cash-line total"><b>Monthly debt total</b><b>${precise(f.debtSpend)}</b></div><p class="note">Each register instalment is counted once. Acceleration checkboxes do not remove contractual payments from the baseline. Interest-only expense estimates are excluded.</p></section><section class="card"><h2>Your income, allocated</h2><div class="cash-line"><span>Take-home income</span><strong>${precise(f.net)}</strong></div><div class="cash-line"><span>Debt payments</span><strong>${precise(f.debtSpend)}</strong></div><div class="cash-line"><span>Remaining after debt</span><strong class="${f.debtRoom<0?'bad':'good'}">${precise(f.debtRoom)}</strong></div><div class="cash-line"><span>Optional living costs</span><strong>${precise(f.optionalSpend)}</strong></div><div class="cash-line"><span>Savings allocation</span><strong>${precise(S.settings.savings)}</strong></div><div class="cash-line total"><b>After chosen costs</b><b class="${f.surplus<0?'bad':'good'}">${precise(f.surplus)}</b></div><p class="note">${f.optionalSpend===0?'Living costs are not included yet. Remaining after debt is not free cash for extra repayments.':'Only your selected living allowances are included.'}</p>${btn('Choose optional costs →','go:plan')}${btn('Try income or loan scenario →','go:scenarios')}</section></div>${advisor()}<section class="card"><div class="row"><h2>Keep the plan current</h2>${btn('Import Standard Bank PDF','go:audit','primary')}</div><p>Latest imported transaction: ${esc(last||'none yet')}. Import each new statement, check returned debits and refresh lender balances monthly.</p><div class="tools">${btn('Historical trends','go:trends')}${btn('Tax & income targets','go:tax')}${btn('Explain all included costs','go:plan')}</div></section>`}
function actions(f,review){return `<div class="step"><b>1. Protect the tax reserve</b><small>Set aside ${money(f.reserve)}/month beyond payroll PAYE under the run-rate scenario.</small></div><div class="step"><b>2. Confirm your debts</b><small>${S.debts.filter(d=>d.apr===null||!d.confirmed).length} accounts need current balances or interest rates. Mortgage stays outside the accelerated plan by default.</small></div><div class="step"><b>3. Reconcile the latest statement</b><small>${review} uncategorised items in the selected month. Import every account and check transfers.</small></div><div class="step"><b>4. ${f.surplus<0?'Close the budget gap':'Choose a realistic extra repayment'}</b><small>${f.surplus<0?money(-f.surplus)+' monthly shortfall before lifestyle allowance.':money(Math.max(0,f.surplus))+' left before extra repayments and lifestyle allowance.'}</small></div>`}
function plan(){let f=F.finance(S),r=monthRows();return `<div class="grid">${metric('Income after tax',f.net)}${metric('Debt payments',f.debtSpend)}${metric('Optional living costs',f.optionalSpend)}${metric('Savings allocation',S.settings.savings)}${metric('Available before extras',f.surplus,'Before extra debt and comfort allowance',f.surplus<0?'bad':'good')}</div>${budgetExplanation()}${payrollCard()}<div class="split"><section class="card"><div class="row"><h2>Optional living costs</h2>${btn('Add category','addBudget')}</div><p class="note">Add only what you want to allow for groceries, fuel and other living costs. Existing historical estimates are excluded until you choose to include them. Debt payments are managed in the debt register and counted once.</p><div class="scroll"><table><thead><tr><th>Included / evidence</th><th>Budget</th><th class="num">Actual selected month</th><th></th></tr></thead><tbody>${S.budgets.map((b,i)=>F.debtCategory(b.category)?'':`<tr class="${b.enabled===false?'budget-excluded':F.budgetReview(b)!=='confirmed'?'budget-review':''}"><td><label><input type="checkbox" data-budget-enabled="${i}" ${b.enabled!==false?'checked':''}> ${esc(b.category)}</label><small>${esc(b.source||'User entered')}</small><label>Evidence status<select data-budget-review="${i}" aria-label="${esc(b.category)} evidence">${opts(['unreviewed','estimate','confirmed'],F.budgetReview(b))}</select></label></td><td><input aria-label="${esc(b.category)} budget" type="number" min="0" step="0.01" value="${b.amount}" data-budget="${i}"></td><td class="num">${money(-F.sum(r.filter(t=>t.category===b.category&&t.amount<0),t=>t.amount))}</td><td>${btn('×','deleteBudget:'+i)}</td></tr>`).join('')}</tbody></table></div></section><section class="card"><div class="row"><h2>Expected income</h2>${btn('Add income','addIncome')}</div>${S.income.map((x,i)=>`<div class="step"><div class="row"><b>${esc(x.name)}</b>${btn('Edit','editIncome:'+i)}</div><div class="row"><span>${money(x.amount)}/month · ${x.active?'active':'excluded'}</span><small>${esc(x.kind)}</small></div><small>${esc(x.source)}</small></div>`).join('')}<h3 style="margin-top:25px">Recurring payment candidates</h3><p class="note">Merchants seen in at least 3 different months. Amount shown is median transaction amount, not a monthly bill. Verify reversals, frequency and cancellations before budgeting.</p>${recurring().slice(0,14).map(x=>`<div class="row"><span>${esc(x.name)}<br><small>${x.months} months · ${x.count} payments</small></span><b>${money(x.median)}</b></div>`).join('')}</section></div>`}
function recurring(){let g={};for(let t of S.transactions.filter(t=>t.amount<0)){let name=t.description.toUpperCase().replace(/\s+\d.*$/,'').replace(/\s+\d{4}\*.*/,'').trim();if(name.length<3||/FEE|PREPAID/.test(name))continue;(g[name]||= []).push(t)}return Object.entries(g).map(([name,r])=>{let a=r.map(t=>-t.amount).sort((a,b)=>a-b);return{name,count:r.length,months:new Set(r.map(t=>t.date.slice(0,7))).size,median:a.length%2?a[(a.length-1)/2]:(a[a.length/2-1]+a[a.length/2])/2}}).filter(x=>x.months>=3).sort((a,b)=>b.median-a.median)}
function transactions(){let r=monthRows().filter(t=>(!filter||t.category===filter)&&(!query||(t.description+' '+t.category).toLowerCase().includes(query.toLowerCase())));return `<section class="card"><div class="row"><div class="tools"><input id="search" placeholder="Search description…" value="${esc(query)}" aria-label="Search transactions"><select id="categoryFilter" aria-label="Filter category"><option value="">All categories</option>${opts(F.cats,filter)}</select></div><div class="tools">${btn('Add transaction','addTransaction')}${btn('Export CSV','exportCSV')}</div></div><p class="note">${r.length} matching transactions. Categories can be changed inline. Reclassification does not change statement amounts or balances.</p><div class="scroll"><table><thead><tr><th>Date</th><th>Description / account</th><th>Category</th><th class="num">Amount</th><th class="num">Balance</th><th></th></tr></thead><tbody>${r.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(t=>`<tr><td>${t.date}</td><td>${esc(t.description)}<br><small>${esc(t.account)}</small></td><td><select aria-label="Transaction category" data-tx="${esc(t.id)}">${opts(F.cats,t.category)}</select></td><td class="num ${t.amount<0?'':'good'}">${precise(t.amount)}</td><td class="num">${t.balance===null?'—':precise(t.balance)}</td><td>${btn('Delete','deleteTx:'+S.transactions.indexOf(t),'danger')}</td></tr>`).join('')}</tbody></table>${r.length?'':'<p class="empty">No matching transactions.</p>'}</div></section>`}
function debts(){let f=F.finance(S),extra=Math.min(S.settings.extraDebt,Math.max(0,f.surplus)),sim=F.simulate(S.debts.map(d=>({...d,include:d.include&&d.confirmed})),extra,S.settings.strategy),included=S.debts.filter(d=>d.include&&d.confirmed);return `${debtStages()}<div class="grid">${metric(S.debtReport?'Unsecured report balance':'Recorded debt balances',S.debtReport?S.debtReport.total:F.sum(S.debts,d=>d.balance),S.debtReport?'Dated creditor figures; not all obligations':'Historical / user figures until refreshed')}${metric('Included for acceleration',F.sum(included,d=>d.balance),'Only confirmed accounts ticked below')}${metric(S.debtReport?'Report instalments / month':'Minimums · included debts',S.debtReport?S.debtReport.minimum:F.sum(included,d=>d.minimum),S.debtReport?'Excludes mortgage, vehicle and other facilities':'Already part of your debt budget')}${metric('Affordable extra payment',extra,'Capped at surplus after savings')}</div>${S.debtReport?`<div class="notice"><b>Report snapshot · data received ${esc(S.debtReport.receivedDate)}</b><br>${esc(S.debtReport.note)} Bank ledger balances are tracked separately; do not add them to the report total without reconciling facilities.</div>`:''}<section class="card"><div class="row"><h2>Debt register</h2>${btn('Add debt','addDebt')}</div><p class="note">Only included accounts with a confirmed current balance enter the simulator. A bank debit confirms a payment, not the outstanding loan principal. Existing balances are dated and need confirmation. APR is intentionally blank where unknown. Repayments do not automatically reduce balances: update from lender statements. Annual fees and daily interest are not modelled.</p><div class="scroll"><table><thead><tr><th>Monthly payment / accelerate</th><th>Account & evidence</th><th class="num">Balance</th><th class="num">Min/month</th><th>APR</th><th></th></tr></thead><tbody>${S.debts.map((d,i)=>`<tr><td><label><input type="checkbox" data-payment-enabled="${i}" ${d.paymentEnabled!==false?'checked':''} ${d.paymentKind==='interest-estimate'?'disabled':''}> Count instalment</label><br><label><input type="checkbox" aria-label="Include ${esc(d.name)}" data-include="${i}" ${d.include?'checked':''}> Accelerate</label></td><td><b>${esc(d.name)}</b><br><small>${esc(d.source)}<br>Balance date ${esc(d.asOf)} · ${d.confirmed?'confirmed':d.reportAccount?'report verified at shown date; current balance needed':'needs confirmation'}</small></td><td class="num">${precise(d.balance)}</td><td class="num">${money(d.minimum)}</td><td>${d.apr===null?'<span class="pill">Missing</span>':d.apr+'%'}</td><td>${btn('Edit','editDebt:'+i)} ${btn('×','deleteDebt:'+i)}</td></tr>`).join('')}</tbody></table></div></section><div class="split" style="margin-top:20px"><section class="card"><h2>Repayment simulator</h2><div class="fields"><label>Repayment strategy<select data-setting="strategy">${opts(['avalanche','snowball'],S.settings.strategy)}</select></label><label>Requested extra / month<input type="number" min="0" data-setting="extraDebt" value="${S.settings.extraDebt}"></label></div>${F.sum(included,d=>d.minimum)>F.debtPayments(S)?'<div class="notice">Accelerated debt minimums exceed counted monthly instalments. Review monthly payment inclusions before relying on this plan.</div>':''}${sim.error?`<div class="notice">${esc(sim.error)}</div>`:`<div class="metric good">${sim.months} months</div><p>Estimated interest: ${money(sim.interest)}. Monthly pool: ${money(F.sum(included,d=>d.minimum)+extra)}. Freed minimums roll to the next debt.</p>${sim.debts.sort((a,b)=>a.paidMonth-b.paidMonth).map(d=>`<div class="row"><span>${esc(d.name)}</span><b>Month ${d.paidMonth}</b></div>`).join('')}`}<p class="note">Avalanche prioritises APR; snowball prioritises the smallest remaining balance. Estimates assume fixed APR, monthly interest, no new borrowing and payments on time.</p></section><section class="card"><h2>Practical next steps</h2>${actions(f,0)}<p class="note">Keep the mortgage current. Confirm arrears and legal collection notices directly with lenders before choosing extra repayments.</p><a href="https://www.consumerfinance.gov/archive/blog/how-reduce-your-debt/" target="_blank" rel="noreferrer">How the two debt strategies work</a></section></div>`}
function taxView(){let f=F.finance(S),y=S.settings.yearProjection,yt=y?F.tax(y.income+y.benefits-y.deductions,S.settings.age,y.credits):0;return `<div class="notice">Tax year 2027: 1 March 2026 to 28 February 2027. Full-year run rate is a scenario, not your actual 2027 tax return. Your employment start date and income changes matter. Business expenses, all income, IRP5 benefits and tax already paid need confirmation. Recheck rates after February 2027.</div><div class="grid">${metric('Annual gross · run rate',f.annual)}${metric('Annual tax · run rate',f.annualTax,'After configured rebates and credits')}${metric('Annual PAYE · run rate',f.paye*12,S.settings.payeMonthly===null?'Modelled PAYE, not verified':'Based on entered monthly PAYE')}${metric('Reserve beyond PAYE',f.reserve,'Per month; not an assessed SARS debt')}</div><div class="split"><section class="card"><h2>Combined-income tax model</h2><div class="fields">${setting('Age at tax year-end','age')}${setting('Annual taxable benefits','taxableBenefits')}${setting('Annual allowable deductions','deductions')}${setting('Annual medical / other tax credits','taxCredits')}${setting('Actual PAYE per month (blank = estimate)','payeMonthly')}${setting('Other cash payroll deductions / month','otherDeductions')}</div><p class="note">Benefits increase taxable income but are not cash. Deductions reduce taxable income; credits reduce tax. Other cash payroll deductions (e.g. UIF and employee provident) reduce spendable cash separately. Employer contributions are not spendable income. Confirm deduction limits and medical scheme membership.</p><div class="row"><span>Total estimated tax / month</span><b>${money(f.annualTax/12)}</b></div><div class="row"><span>Net available after all tax & payroll deductions</span><b>${money(f.net)}</b></div><p><a href="https://www.sars.gov.za/tax-rates/income-tax/rates-of-tax-for-individuals/" target="_blank" rel="noreferrer">SARS tax tables</a> · <a href="https://www.sars.gov.za/types-of-tax/provisional-tax/" target="_blank" rel="noreferrer">Provisional tax</a></p></section><section class="card"><h2>What does a decent month cost?</h2><p class="note">An editable lifestyle scenario, not a universal living-cost benchmark. Covers your chosen living-cost target (including mortgage and minimum debt payments), savings, additional debt repayment and comfort allowance. Compare it with the spending plan: reducing a target does not reduce actual bills.</p><div class="fields">${setting('Living costs + minimum debts / month (blank = budget)','lifestyleBase')}${setting('Emergency / long-term savings per month','savings')}${setting('Extra debt repayment per month','extraDebt')}${setting('Lifestyle / contingency allowance per month','comfort')}</div><div class="row"><span>Required net monthly income</span><b>${money(f.desired)}</b></div><div class="row"><span>Additional net income needed</span><b>${money(f.extraNet)}</b></div><div class="row"><span>Additional gross income needed</span><b class="bad">${money(f.extraGross)}</b></div><p class="note">Gross-up uses the same 2027 tax bands and fixed benefits/deductions. Extra business income means taxable profit; costs needed to earn it are additional. New employment could add pension or other deductions.</p></section></div>${y?`<section class="card"><h2>Actual tax-year projection · 2027</h2><p class="note">${esc(S.settings.yearProjectionNote||'Enter your actual and expected income for March to February, benefits, allowable deductions, credits and PAYE. Blank-state zeros mean information is missing, not tax-free income.')}</p><div class="fields">${yearField('Total gross income during tax year','income')}${yearField('Taxable benefits / additions during year','benefits')}${yearField('Allowable deductions during year','deductions')}${yearField('Medical / other tax credits during year','credits')}${yearField('PAYE for full tax year','paye')}${yearField('Provisional / other tax payments already made','paid')}</div><div class="row"><span>Projected total income tax</span><b>${money(yt)}</b></div><div class="row"><span>Projected remaining tax after PAYE and entered payments</span><b>${money(yt-y.paye-y.paid)}</b></div><small>A positive balance is a projected reserve need, not verified tax arrears. Interest, penalties and past-year balances excluded.</small></section>`:''}`}
function setting(label,k){return `<label>${label}<input type="number" min="0" step="0.01" data-setting="${k}" value="${S.settings[k]??''}"></label>`}
function yearField(label,k){return `<label>${label}<input type="number" min="0" step="0.01" data-year="${k}" value="${S.settings.yearProjection[k]}"></label>`}
function auditView(){let r=monthRows(),un=r.filter(t=>t.category==='Other / review').length,rev=r.filter(t=>t.amount>0&&/AUTOPAY/.test(t.description.toUpperCase()));return `<div class="split"><section class="card"><h2>1. Import a Standard Bank PDF</h2><p>Upload your Standard Bank 6-month PDF, in the same format as your previous statements. Processing stays on this PC. Preview the dates, totals and account before saving.</p><div class="tools"><input id="importFile" type="file" accept=".csv,.pdf" aria-label="Import statement"></div><p class="note">Start-Finance.bat prepares PDF support on first run. Supported: text-based Standard Bank statements, including both layouts already supplied. Scanned or encrypted files are rejected with guidance. CSV remains an optional advanced format.</p><h3>2. Reconcile balances</h3><p class="note">For ${esc(month)}, enter statement opening and closing balances for one account. Use the exact same date range. Partial months are valid; they are not full-month audits.</p><form id="auditForm"><div class="fields"><label>Account<select name="account">${opts([...new Set([(S.transactions[0]?.account||'Main account'),...S.transactions.map(t=>t.account)])],(S.transactions[0]?.account||'Main account'))}</select></label><label>Period start<input name="from" type="date" required value="${month}-01"></label><label>Period end<input name="to" type="date" required value="${new Date(Date.UTC(Number(month.slice(0,4)),Number(month.slice(5)),0)).toISOString().slice(0,10)}"></label><label>Opening balance<input name="opening" type="number" step="0.01" required></label><label>Closing balance<input name="closing" type="number" step="0.01" required></label></div>${btn('Calculate & record audit','submitAudit','primary')}</form></section><section class="card"><h2>Monthly review checklist</h2><div class="step"><b>${r.length} transactions in ${esc(month)}</b><small>Import every account before treating household totals as complete.</small></div><div class="step"><b>${un} items need categorisation</b><small>Resolve Other / review in Transactions.</small></div><div class="step"><b>${rev.length} possible repayment reversals</b><small>Match returned debits against payments. A reversed debit may mean the debt is unpaid.</small></div><div class="step"><b>Refresh lender statements</b><small>Update each principal balance, APR, minimum and balance date. Debits alone cannot establish balances.</small></div><div class="step"><b>Refresh payroll & tax</b><small>Compare salary, PAYE and retirement deductions with the latest payslip.</small></div><div class="step"><b>Review next month’s recurring costs</b><small>Check cancellations, annual renewals, transfers and variable income.</small></div><p class="notice">Due next: review the previous calendar month by the 5th. This is an in-app checklist; no background bank connection or notification service is enabled.</p></section></div><section class="card"><h2>Reconciliation history</h2><p class="note">Active audits recalculate from the ledger. Superseded audits retain their original source calculation; backdated reversals and posted authorisations can change overlapping periods.</p><div class="scroll"><table><thead><tr><th>Account / period</th><th class="num">Opening</th><th class="num">Calculated close</th><th class="num">Statement close</th><th>Status</th></tr></thead><tbody>${S.audits.map(a=>{let rows=S.transactions.filter(t=>t.account===a.account&&t.date>=a.from&&t.date<=a.to),v=F.audit(rows,a.opening,a.closing);return `<tr><td>${esc(a.account)}<br>${a.from} to ${a.to}</td><td class="num">${precise(a.opening)}</td><td class="num">${precise(a.superseded&&Number.isFinite(a.sourceNet)?a.opening+a.sourceNet:v.expected)}</td><td class="num">${precise(a.closing)}</td><td class="${a.superseded?'muted':Math.abs(v.difference)<.01?'good':'bad'}">${a.superseded?'Superseded by newer statement':Math.abs(v.difference)<.01?'Balanced':'Difference '+precise(v.difference)}${a.note?'<br><small>'+esc(a.note)+'</small>':''}</td></tr>`}).join('')}</tbody></table></div></section>`}
function settings(){return `<div class="split"><section class="card"><h2>Evidence register</h2><p class="note">A date and source travel with each figure. Old data does not become current by importing it.</p>${(S.evidence||[]).map(e=>`<div class="step"><b>${esc(e.title)}</b><small>${esc(e.detail)}</small></div>`).join('')||'<p>Start by adding income, budgets and debts.</p>'}<h3 style="margin-top:25px">Still needed</h3><p>${esc(S.missing||'Latest salary and tax certificates, current lender balances and APRs, statements for every account, annual costs and savings balances.')}</p></section><section class="card"><h2>Backups & privacy</h2><p>${serverMode?'SQLite database in data/finance.sqlite3 beside this app. The last 100 saved states are retained locally.':'Browser-only mode: data lives in this browser profile. Clearing browser storage may erase it.'}</p><div class="tools">${btn('Export complete backup','backup','primary')}<label style="margin:0">Restore JSON<input type="file" id="restoreFile" accept=".json"></label></div><p class="notice">Data and backups are unencrypted. Use your PC’s disk encryption and keep private backups away from public repositories. Export a backup before moving folders, switching modes or upgrading.</p><p>No bank credentials, analytics, external fonts or remote AI requests. Importing a new statement never silently changes your budget.</p><h3>Run locally</h3><p>Windows: extract the whole folder and double-click Start-Finance.bat. Requires Python 3.10+. Start-Finance.bat prepares PDF support automatically on first run. Setup needs internet once; statements are processed locally.</p>${btn('Print this screen','print')}</section></div>`}
function modal(title,body,onSubmit,wide=false){let d=$('#dialog');d.className=wide?'wide':'';d.innerHTML=`<form id="modalForm"><div class="row"><h2>${esc(title)}</h2><button type="button" id="closeModal" aria-label="Close">×</button></div>${body}<div class="tools" style="margin-top:20px"><button type="submit" class="primary">Save</button><button type="button" id="cancelModal">Cancel</button></div></form>`;$('#closeModal').onclick=$('#cancelModal').onclick=()=>d.close();$('#modalForm').onsubmit=e=>{e.preventDefault();try{onSubmit(new FormData(e.target));d.close();save(title+' saved');render()}catch(e){toast(e.message)}};d.showModal()}
const field=(label,name,value='',type='text',required=true)=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'step="0.01" min="0"':''}></label>`;
function incomeModal(i){let x=S.income[i]||{name:'',amount:0,kind:'contract',source:'User entered',active:true};modal('Expected income',`<div class="fields">${field('Income source','name',x.name)}${field('Monthly gross / taxable profit','amount',x.amount,'number')}<label>Type<select name="kind">${opts(['salary','contract','business'],x.kind)}</select></label>${field('Source & date','source',x.source)}<label>Include in forecast<input name="active" type="checkbox" ${x.active?'checked':''}></label></div>`,f=>{let z={...x,name:f.get('name'),amount:+f.get('amount'),kind:f.get('kind'),source:f.get('source'),active:f.has('active')};if(i>=0)S.income[i]=z;else S.income.push(z)})}
function debtModal(i){let d=S.debts[i]||{name:'',balance:0,minimum:0,apr:null,source:'User entered',asOf:today(),include:false,confirmed:false};modal('Debt details',`<div class="fields">${field('Lender / account nickname','name',d.name)}${field('Outstanding principal','balance',d.balance,'number')}${field('Contractual minimum / month','minimum',d.minimum,'number')}${field('APR % (blank if unknown)','apr',d.apr??'','number',false)}${field('Balance date','asOf',d.asOf,'date')}${field('Source / evidence','source',d.source)}<label>Payment figure type<select name="paymentKind">${opts(['contractual','interest-estimate'],d.paymentKind||'contractual')}</select></label><label>Count in monthly debt payments<input name="paymentEnabled" type="checkbox" ${d.paymentEnabled!==false?'checked':''}></label><label>Current balance confirmed<input name="confirmed" type="checkbox" ${d.confirmed?'checked':''}></label><label>Include in accelerated plan<input name="include" type="checkbox" ${d.include?'checked':''}></label></div>`,f=>{let z={...d,paymentKind:f.get('paymentKind'),paymentEnabled:f.has('paymentEnabled'),name:f.get('name'),balance:+f.get('balance'),minimum:+f.get('minimum'),apr:f.get('apr')===''?null:+f.get('apr'),asOf:f.get('asOf'),source:f.get('source'),include:f.has('include'),confirmed:f.has('confirmed')};if(z.apr>1000)throw Error('Check the annual interest rate');if(i>=0)S.debts[i]=z;else S.debts.push(z)})}
async function importStatement(file){try{let rows,meta=null;if(file.name.toLowerCase().endsWith('.pdf')){if(!serverMode)throw Error('Open Start-Finance.bat to import your Standard Bank PDF locally.');toast('Reading statement locally…');let r=await fetch('/api/pdf',{method:'POST',headers:{'Content-Type':'application/pdf','X-Finance-Local':'1'},body:file}),j=await r.json();if(!r.ok)throw Error(j.error);rows=j.transactions.map(t=>({...t,category:F.classify(t.description+' '+(t.details||''),t.amount)}));meta=j}else rows=F.readCSV(await file.text());if(!rows.length)throw Error('No transaction rows found');pending={rows,meta};modal('Review statement import',`<div class="notice">${rows.length} rows · ${money(F.sum(rows.filter(t=>t.amount>0),t=>t.amount))} deposits · ${money(-F.sum(rows.filter(t=>t.amount<0),t=>t.amount))} payments. ${meta?'Standard Bank · account ending '+esc(meta.accountLast4||'not detected')+' · '+esc(meta.from)+' to '+esc(meta.to)+' · opening '+precise(meta.opening)+' · closing '+precise(meta.closing)+' · '+(meta.summaryVerified?'printed summary verified':'printed summary unavailable; running balances verified'):''} Review the preview and compare totals with your original statement. Saving a PDF refresh records its balance reconciliation. Review categories and lender figures separately.</div>${field('Account nickname for rows without an account column','account',(S.transactions[0]?.account||'Main account'))}${meta?'<input type="hidden" name="mode" value="refresh"><b>Refresh this statement period safely</b><p class="note">Refresh preserves manual entries and matched categories, archives overlapping audits and records the new statement balance check. Export a backup first. This handles changed references, backdated reversals and settled authorisations.</p>':''}<p class="note">Exact matches in this account are skipped. For CSV without balances, overlapping statements with repeated identical transactions can be ambiguous. Reconcile after importing.</p><div class="scroll" style="max-height:320px"><table><thead><tr><th>Date</th><th>Description</th><th>Amount</th><th>Category</th></tr></thead><tbody>${rows.slice(0,100).map(t=>`<tr><td>${t.date}</td><td>${esc(t.description)}</td><td>${precise(t.amount)}</td><td>${esc(t.category)}</td></tr>`).join('')}</tbody></table></div><p class="note">Preview: first ${Math.min(100,rows.length)} rows. Categories editable after import.</p>`,f=>{let account=f.get('account').trim();if(!account)throw Error('Account name required');if(meta?.accountLast4&&S.audits.some(a=>a.account===account&&a.accountLast4&&a.accountLast4!==meta.accountLast4))throw Error('This nickname belongs to a different bank account. Choose another nickname.');let incoming=F.identities(rows,account),ids=new Set(S.transactions.map(t=>t.id)),fresh=incoming.filter(t=>!ids.has(t.id));if(meta&&f.get('mode')==='refresh'){F.refreshStatement(S,incoming,account,meta.from,meta.to,{opening:meta.opening,closing:meta.closing,date:today(),source:file.name,accountLast4:meta.accountLast4});}else S.transactions.push(...fresh);S.imports||=[];let summary=meta?Object.fromEntries(Object.entries(meta).filter(([k])=>k!=='transactions')):null;S.imports.push({file:file.name,date:today(),rows:rows.length,account,meta:summary});pending=null},true)}catch(e){toast(e.message)}}
document.addEventListener('click',e=>{let nav=e.target.closest('[data-view]');if(nav){view=nav.dataset.view;document.body?.classList.remove('menu-open');$('#menuToggle')?.setAttribute?.('aria-expanded','false');render();return}let b=e.target.closest('[data-action]');if(!b)return;let [a,n]=b.dataset.action.split(':'),i=Number(n);if(a==='applyScenarioIncome'){modal('Add scenario income to plan',`${field('Income name','name','Additional income')}${field('Monthly gross income (enter gross, not net)','amount',0,'number')}<p class="note">The what-if figure is after-tax cash. Enter the gross amount here so the plan can calculate tax. This creates an ongoing income line; review its active dates.</p>`,f=>S.income.push({name:f.get('name'),amount:+f.get('amount'),active:true,kind:'business',source:'User-confirmed scenario income'}))}else if(a==='toggleMenu'){let open=document.body.classList.toggle('menu-open');$('#menuToggle').setAttribute('aria-expanded',String(open));return}else if(a==='retrySave'){save()}else if(a==='assistant'){assistantModal()}else if(a==='latestMonth'){let last=S.transactions.map(t=>t.date).sort().at(-1);if(last)month=last.slice(0,7);view='transactions';render()}else if(a==='go'){view=n;render()}else if(a==='backup')download('finance-backup-'+today()+'.json',JSON.stringify(S,null,2));else if(a==='print')window.print();else if(a==='addIncome')incomeModal(-1);else if(a==='editIncome')incomeModal(i);else if(a==='addDebt')debtModal(-1);else if(a==='editDebt')debtModal(i);else if(a==='addBudget')modal('Add budget category',`<label>Category<select name="category">${opts(F.cats.filter(c=>!['Salary','Contract income','Business income','Loan proceeds','Transfers / refunds'].includes(c)&&!F.debtCategory(c)))}</select></label>${field('Monthly amount','amount',0,'number')}`,f=>{let category=f.get('category');if(S.budgets.some(b=>b.category===category))throw Error('This category already has a budget');S.budgets.push({category,amount:+f.get('amount'),source:'User entered',review:'unreviewed'})});else if(a==='addTransaction')modal('Add transaction',`<div class="fields">${field('Date','date',today(),'date')}${field('Description','description')}${field('Account','account',(S.transactions[0]?.account||'Main account'))}<label>Signed amount (negative = spending)<input type="number" name="amount" step="0.01" required></label><label>Category<select name="category">${opts(F.cats,'Other / review')}</select></label></div>`,f=>S.transactions.push({id:'manual:'+uid(),date:f.get('date'),description:f.get('description'),account:f.get('account'),amount:+f.get('amount'),balance:null,category:f.get('category')}));else if(a==='deleteBudget'||a==='deleteDebt'||a==='deleteTx'){if(confirm('Delete this record? Export a backup first if you may need it.')){S[a==='deleteBudget'?'budgets':a==='deleteDebt'?'debts':'transactions'].splice(i,1);save();render()}}else if(a==='csvTemplate')download('statement-template.csv','date,description,amount,balance,category\n2026-10-01,Example grocery purchase,-250.00,,Groceries\n','text/csv');else if(a==='exportCSV'){let q=x=>'"'+String(x??'').replace(/"/g,'""')+'"';download('transactions-'+month+'.csv',['date,description,amount,balance,category,account',...monthRows().map(t=>[t.date,t.description,t.amount,t.balance,t.category,t.account].map(q).join(','))].join('\n'),'text/csv')}else if(a==='submitAudit'){$('#auditForm').requestSubmit()}});
document.addEventListener('change',async e=>{let t=e.target;if(t.id==='month'){month=t.value;render()}else if(t.dataset.budget!==undefined){let n=+t.value;if(t.value===''||!Number.isFinite(n)||n<0)return toast('Enter a non-negative budget');S.budgets[+t.dataset.budget].amount=n;save('Budget updated');render()}else if(t.dataset.budgetEnabled!==undefined){S.budgets[+t.dataset.budgetEnabled].enabled=t.checked;save('Forecast inclusion updated');render()}else if(t.dataset.budgetReview!==undefined){S.budgets[+t.dataset.budgetReview].review=t.value;save('Evidence status updated');render()}else if(t.dataset.tx){S.transactions.find(x=>x.id===t.dataset.tx).category=t.value;save()}else if(t.dataset.paymentEnabled!==undefined){S.debts[+t.dataset.paymentEnabled].paymentEnabled=t.checked;save('Debt payment inclusion updated');render()}else if(t.dataset.include!==undefined){S.debts[+t.dataset.include].include=t.checked;save();render()}else if(t.dataset.setting){let k=t.dataset.setting,v=k==='strategy'?t.value:['payeMonthly','lifestyleBase'].includes(k)&&t.value===''?null:+t.value;if(v!==null&&typeof v==='number'&&(!Number.isFinite(v)||v<0))return toast('Enter a non-negative value');S.settings[k]=v;save();render()}else if(t.dataset.year){let n=+t.value;if(n<0||!Number.isFinite(n))return toast('Enter a non-negative value');S.settings.yearProjection[t.dataset.year]=n;save();render()}else if(t.id==='categoryFilter'){filter=t.value;render()}else if(t.id==='importFile'&&t.files[0])await importStatement(t.files[0]);else if(t.id==='restoreFile'&&t.files[0]){try{let s=F.valid(JSON.parse(await t.files[0].text()));F.enableDebtFocus(s);if(confirm('Replace all current data with this backup? Export your current backup first.')){S=s;save('Backup restored');render()}}catch(e){toast(e.message)}}});
document.addEventListener('input',e=>{let t=e.target;if(t.dataset.scenario){scenario[t.dataset.scenario]=t.dataset.scenario==='start'?t.value:+t.value;let target=$('#scenarioResults');try{target.innerHTML=scenarioResults()}catch(err){target.textContent=err.message}return}if(t.dataset.budget!==undefined){let n=+t.value;if(t.value===''||!Number.isFinite(n)||n<0){clearTimeout(autoSaveTimer);status('Enter a valid amount');return}S.budgets[+t.dataset.budget].amount=n;liveBudget();status('Unsaved edits…');clearTimeout(autoSaveTimer);autoSaveTimer=setTimeout(()=>save('Budget updated'),650)}else if(e.target.id==='search'){let pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});
document.addEventListener('submit',e=>{if(e.target.id==='auditForm'){e.preventDefault();let f=new FormData(e.target),from=f.get('from'),to=f.get('to');if(from>to)return toast('Start date must be before end date');let a={account:f.get('account'),from,to,opening:+f.get('opening'),closing:+f.get('closing'),date:today()},r=S.transactions.filter(t=>t.account===a.account&&t.date>=from&&t.date<=to);if(!r.length)return toast('No transactions for this account and period');S.audits.push(a);save('Audit recorded; review the difference');render()}});
(async()=>{try{let seed=JSON.parse($('#seed').textContent);if(serverMode){let r=await fetch('/api/state');if(!r.ok)throw Error('Cannot read local database');S=F.valid(await r.json()||seed)}else{let stored=localStorage.getItem(key);S=F.valid(stored?JSON.parse(stored):seed)}lastSnapshot=JSON.parse(JSON.stringify(S));let corrected=F.applyCorrections(S,seed),focused=F.enableDebtFocus(S);if(corrected||focused)save(focused?'Income and debt focus saved; optional costs preserved and excluded':'Verified document updates saved');render();if(!pendingWrites)status(serverMode?'Local database · ready':'Browser storage · export backups');}catch(e){$('#content').innerHTML='<div class="notice">Could not load your data. '+esc(e.message)+' Do not clear storage. Check your backup or restart the local server.</div>'}})();

document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body?.classList.remove('menu-open');$('#menuToggle')?.setAttribute?.('aria-expanded','false')}});

function payrollCard(){let p=S.payroll;if(!p)return '';return `<section class="card" style="margin-bottom:20px"><div class="section-top"><h2>Verified payroll baseline</h2><span class="pill">Payslip · ${esc(p.asOf)}</span></div><p class="note">${esc(p.source)}. Forecast assumes this pay and these deductions continue. Employer-paid benefits are not added to spendable income.</p><div class="forecast-points"><div><small>Monthly gross</small><strong>${money(p.gross)}</strong></div><div><small>PAYE</small><strong>${money(p.paye)}</strong></div><div><small>UIF + employee provident</small><strong>${money(p.uif+p.employeeProvident)}</strong></div><div><small>Expected net cash</small><strong class="good">${precise(p.net)}</strong></div></div><p class="note" style="margin-top:14px;margin-bottom:0">Total payroll deductions: ${precise(p.deductions)}/month. Annualised net: ${precise(p.net*12)}; actual tax-year earnings depend on employment dates and other income.</p></section>`}

function budgetExplanation(){let b=F.budgetBreakdown(S);return `<section class="card budget-explanation"><div class="row"><h2>Income first. Debt payments next. Optional costs are your choice.</h2><span class="pill">All included categories, once</span></div><p>Debt instalments come from your debt register. This replaces the old aggregate debt budget so the same debt is not counted twice. Non-debt estimates are preserved below but excluded by default. Dated lender amounts still need current confirmation.</p><div id="liveBudget" class="notice" aria-live="polite">Debt + optional costs ${precise(b.total)} · take-home ${precise(F.finance(S).net)} · shortfall / available ${precise(F.finance(S).surplus)}</div><div class="forecast-points"><div><small>Marked confirmed by you</small><strong>${money(b.confirmed)}</strong></div><div><small>Estimates / unreviewed</small><strong>${money(b.review)}</strong></div><div><small>Excluded from forecast</small><strong>${money(b.excluded)}</strong></div></div><details open><summary>Every included amount, largest first</summary>${b.rows.filter(x=>x.enabled).map(x=>`<div class="cash-line"><span>${esc(x.category)} <small class="pill">${esc(x.review)}</small><small class="source-line">${esc(x.source||'User entered; evidence not supplied')}</small></span><b>${precise(x.amount)}</b></div>`).join('')}<div class="cash-line total"><b>Total</b><b>${precise(b.total)}</b></div></details><p class="note">Mortgage and vehicle instalments are debt payments. Overdraft interest proxies are not confirmed minimums. Historical shopping, groceries and fuel are optional: edit and tick them only when you choose a budget. Remaining after debt is not free cash until living costs are allowed for.</p><p class="notice">${esc(S.focusMigration?.note||'Debt payments and optional costs are counted separately.')}</p><details><summary>Recent saved changes (${(S.changeLog||[]).length} batches)</summary>${(S.changeLog||[]).slice(-12).reverse().map(c=>`<div class="step"><b>${esc(new Date(c.at).toLocaleString())}</b>${c.items.map(x=>`<small>${esc(x.section)} · ${esc(x.label)}: ${esc(changeValue(x.before))} → ${esc(changeValue(x.after))}</small>`).join('')}</div>`).join('')||'<p>Change tracking starts with this update. Earlier edits have no reliable timestamp.</p>'}</details></section>`}
function changeValue(x){if(x===null)return 'removed / not set';if(typeof x!=='object')return String(x);if('amount' in x)return precise(x.amount)+' · '+(x.enabled===false?'excluded':'included')+' · '+F.budgetReview(x);return JSON.stringify(x)}
function advisor(){return `<section class="card advisor"><div class="row"><h2>Your local finance assistant</h2>${btn('Ask local AI','assistant')}</div><p class="note">These suggestions recalculate from your saved plan. Built-in checks use transparent rules. Optional AI requires a local Ollama model and cannot change your records.</p><div class="split">${F.insights(S).map(i=>`<div class="step"><b>${esc(i.title)}</b><p>${esc(i.detail)}</p>${btn('Review →','go:'+i.view)}</div>`).join('')}</div></section>`}
function debtStages(){let f=F.finance(S),missing=S.debts.filter(d=>d.include&&(!d.confirmed||d.apr===null));return `<section class="card"><h2>Your debt buster plan</h2><div class="step"><b>1. Stabilise this month ${f.surplus<0?'· action needed':'· funded by your plan'}</b><small>${f.surplus<0?'Close the '+precise(-f.surplus)+' forecast gap. No extra repayments are allocated while the plan is negative. Review estimates, protect essentials and contact lenders about minimums you cannot afford.':'Your plan has '+precise(f.surplus)+' after chosen costs and savings. Allow for living expenses and an emergency buffer before extra debt repayments.'}</small></div><div class="step"><b>2. Complete lender information · ${missing.length} included accounts incomplete</b><small>Confirm current balances, APRs, minimums and arrears in the register. Returned debits are not paid instalments. Dated credit-report figures are a starting point.</small></div><div class="step"><b>3. Accelerate and review monthly</b><small>Use ${esc(S.settings.strategy)} with an affordable extra capped at ${precise(Math.max(0,Math.min(f.surplus,S.settings.extraDebt)))}. The simulator rolls freed minimums to the next debt. Re-import PDFs monthly and update lender balances.</small></div></section>`}
function assistantModal(){modal('Ask your local AI',`<p>Optional: install Ollama and download a local model on this PC. Enter its exact installed name. Cloud models are blocked. Only budget summaries and debt readiness are sent to your local model, not statements or account numbers.</p><label>Installed local model<input id="aiModel" required placeholder="Exact model name from ollama list"></label><label>Question<textarea id="aiQuestion" maxlength="1500" required>Explain my spending total and the next practical step to reduce debt.</textarea></label><button type="button" data-action="askAI">Ask assistant</button><pre id="aiAnswer" aria-live="polite">AI replies are suggestions. Check the figures against your plan.</pre>`,()=>{});$('#modalForm button[type="submit"]').style.display='none';}
document.addEventListener('click',async e=>{if(e.target.closest('[data-action="askAI"]')){let target=$('#aiAnswer'),question=$('#aiQuestion').value,model=$('#aiModel').value;if(!question.trim()||!model.trim())return toast('Enter a model and question');if(!serverMode)return toast('Open Start-Finance.bat for local AI');let button=e.target;button.disabled=true;target.textContent='Thinking locally…';try{let f=F.finance(S),b=F.budgetBreakdown(S),r=await fetch('/api/advisor',{method:'POST',headers:{'Content-Type':'application/json','X-Finance-Local':'1'},body:JSON.stringify({model,question,facts:{takeHome:f.net,plannedCosts:f.spend,savings:S.settings.savings,surplus:f.surplus,budgets:b.rows.map(x=>({category:x.category,amount:x.amount,included:x.enabled,status:x.review})),readiness:F.insights(S).map(x=>({title:x.title,detail:x.detail.replace(/Confirm current principal, APR and minimum for:.*?No reliable/,'Confirm missing lender details. No reliable')}))}})}),j=await r.json();if(!r.ok)throw Error(j.error);target.textContent=j.answer}catch(e){target.textContent=e.message}finally{button.disabled=false}}});
globalThis.addEventListener?.('beforeunload',e=>{if(autoSaveTimer||pendingWrites){e.preventDefault();e.returnValue='Changes are still saving'}});

function trends(){let months=[...new Set(S.transactions.map(t=>t.date.slice(0,7)))].sort();return `<section class="card"><h2>Historical trends</h2><p>Actual bank movement, kept separate from your debt-first forecast. Deposits can include refunds, transfers and borrowing. Partial months are labelled.</p><div class="scroll"><table><thead><tr><th>Month</th><th>Earned income categories</th><th>Other deposits</th><th>Debt payments recorded</th><th>Other outflows</th><th>Net bank movement</th><th>Coverage</th></tr></thead><tbody>${months.map(m=>{let r=monthRows(m),earned=F.sum(r.filter(t=>t.amount>0&&['Salary','Contract income','Business income'].includes(t.category)),t=>t.amount),inc=F.sum(r.filter(t=>t.amount>0),t=>t.amount),out=-F.sum(r.filter(t=>t.amount<0),t=>t.amount),debt=-F.sum(r.filter(t=>t.amount<0&&F.debtCategory(t.category)),t=>t.amount),last=new Date(Date.UTC(+m.slice(0,4),+m.slice(5),0)).toISOString().slice(0,10),full=S.audits.some(a=>!a.superseded&&a.from<=m+'-01'&&a.to>=last);return `<tr><td>${m}</td><td>${precise(earned)}</td><td>${precise(inc-earned)}</td><td>${precise(debt)}</td><td>${precise(out-debt)}</td><td>${precise(inc-out)}</td><td>${full?'Period covered':'Partial / coverage unconfirmed'}</td></tr>`}).join('')}</tbody></table></div><p class="note">Classification can need correction. Recorded debt outflows may include later returned debits; audit these before treating them as paid instalments. These totals never become fixed monthly budgets automatically.</p></section><section class="card"><h2>Category trends</h2><div class="scroll"><table><thead><tr><th>Category</th>${months.map(m=>`<th>${m}</th>`).join('')}</tr></thead><tbody>${F.cats.filter(c=>S.transactions.some(t=>t.category===c&&t.amount<0)).map(c=>`<tr><td>${esc(c)}</td>${months.map(m=>`<td>${money(-F.sum(monthRows(m).filter(t=>t.category===c&&t.amount<0),t=>t.amount))}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`}
function scenarios(){return `<section class="card"><h2>Try extra income or a proposed loan</h2><p>Scenarios leave your live plan unchanged. Enter expected extra take-home cash and any additional tax reserve yourself. Loan proceeds are borrowing, shown separately from income.</p><div class="fields">${[['Start month','start','month'],['Extra take-home / month','extraIncome','number'],['Income lasts (months)','incomeMonths','number'],['Additional tax reserve / month','extraTax','number'],['Proposed loan repayment / month','payment','number'],['Repayment term (months)','term','number'],['Loan cash received at start (optional)','principal','number']].map(([label,k,type])=>`<label>${label}<input type="${type}" min="0" max="${['term','incomeMonths'].includes(k)?120:''}" step="${['term','incomeMonths'].includes(k)?1:.01}" data-scenario="${k}" value="${scenario[k]}"></label>`).join('')}</div><p class="note">Uses your current take-home, counted debt instalments, selected optional costs and savings. Repayments start in the selected month. Enter the lender’s full monthly repayment including fees and insurance. Existing debts are assumed to continue; this is not an amortisation or affordability approval.</p></section><div id="scenarioResults" aria-live="polite">${scenarioResults()}</div>`}
function scenarioResults(){let rows=F.cashflow(S,scenario),total=F.round((+scenario.payment||0)*(+scenario.term||0)),min=Math.min(...rows.map(r=>r.operating));return `<div class="grid">${metric('Total proposed repayments',total,'Repayment × term')}${metric('First month operating cash',rows[0].operating,'Excludes the new loan proceeds')}${metric('Lowest monthly operating cash',min,'Within the displayed horizon',min<0?'bad':'good')}${metric('Cumulative cash movement',rows.at(-1).cumulative,rows.length+' months; includes borrowing, not a bank balance')}</div><section class="card"><h2>Month-by-month cash flow</h2><p class="notice">${F.finance(S).optionalSpend===0?'No living costs are included. Money left after debt must still cover your real living expenses.':'Only your selected living costs are included.'} Extra income is assumed to be after tax, less your additional reserve.</p><div class="scroll"><table><thead><tr><th>Month</th><th>Net income</th><th>Existing debt</th><th>Optional costs + savings</th><th>New repayment</th><th>Operating surplus / gap</th><th>Borrowing received</th><th>Cumulative movement</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.month}</td><td>${precise(r.income)}</td><td>${precise(r.debt)}</td><td>${precise(r.optional+r.savings)}</td><td>${precise(r.repayment)}</td><td class="${r.operating<0?'bad':'good'}">${precise(r.operating)}</td><td>${precise(r.borrowing)}</td><td>${precise(r.cumulative)}</td></tr>`).join('')}</tbody></table></div><p class="note">A loan receipt can make cumulative cash positive while monthly cash flow is negative. Horizon is at least 12 months and extends to the longer income or repayment term, up to 120 months. No values are added to your budget automatically.</p></section>`}
